/* HEXA BATTLEGROUNDS setup — PART 36 OF 79. Run parts in order. Safe to re-run. */ create or replace function captain_submit(p_token text, p_instance uuid, p_answers jsonb, p_idem text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; mi mission_instances; mt mission_templates; s submissions; v_ok boolean := true; v_part jsonb; v_given text; v_i int := 0; v_n int; v_pts int := 0; v_raw text; begin p := _auth_captain(p_token); if p_idem is null or length(p_idem) < 8 then raise exception 'BAD_REQUEST'; end if; select * into s from submissions where idem_key = p_idem; if s.id is not null then select * into mi from mission_instances where id = s.instance_id; return jsonb_build_object('correct', s.correct, 'status', mi.status, 'attempts_left', mi.attempts_left, 'points', mi.points_awarded, 'replayed', true); end if; select * into mi from mission_instances where id = p_instance for update; if mi.id is null or mi.team_id <> p.team_id then raise exception 'NOT_FOUND'; end if; if mi.status <> 'active' then raise exception 'NOT_ACTIVE'; end if; if mi.deadline <= now() then perform _fail(mi.id, 'expired'); raise exception 'EXPIRED'; end if; select * into mt from mission_templates where id = mi.template_id; v_n := jsonb_array_length(mt.parts); if jsonb_typeof(p_answers) <> 'array' or jsonb_array_length(p_answers) <> v_n then raise exception 'BAD_ANSWER_FORMAT'; end if; for v_part in select value from jsonb_array_elements(mt.parts) loop v_given := _norm(p_answers ->> v_i); if not exists (select 1 from jsonb_array_elements_text(v_part -> 'accept') acc where (acc = '{KEY}' and v_given = _norm(mi.relay_key)) or (acc <> '{KEY}' and acc = v_given)) then v_ok := false; end if; v_i := v_i + 1; end loop; select string_agg(value, ' | ') into v_raw from jsonb_array_elements_text(p_answers); insert into submissions(instance_id, team_id, player_id, answer, correct, idem_key) values (mi.id, mi.team_id, p.id, left(coalesce(v_raw, ''), 300), v_ok, p_idem); if v_ok then v_pts := _complete(mi.id); else update mission_instances set attempts_left = attempts_left - 1 where id = mi.id returning * into mi; if mi.attempts_left > 0 and mi.sync_round_id is null and mi.kind in ('mission', 'relay', 'airdrop') then perform _damage(mi.team_id, _cfg((select event_id from teams where id = mi.team_id), 'dmg_wrong'), 'wrong_answer', mi.id::text || ':' || mi.attempts_left, 'Wrong answer'); end if; if mi.attempts_left <= 0 then perform _fail(mi.id, 'failed'); end if; perform _ping_team(mi.team_id, 'attempt'); end if; select * into mi from mission_instances where id = mi.id; return jsonb_build_object('correct', v_ok, 'status', mi.status, 'attempts_left', mi.attempts_left, 'points', mi.points_awarded); end $$; create or replace function _complete(p_instance uuid) returns int language plpgsql as $$ declare mi mission_instances; mt mission_templates; t teams; l locations; sr sync_rounds; v_ev uuid; v_pts int := 0; v_coins int := 0; v_item text; v_won boolean; ad airdrops; v_total numeric; v_left numeric; begin select * into mi from mission_instances where id = p_instance for update; if mi.status <> 'active' then return 0; end if; select * into mt from mission_templates where id = mi.template_id; select * into t from teams where id = mi.team_id; v_ev := t.event_id; update mission_instances set status = 'solved', solved_at = now() where id = mi.id; if mi.kind = 'battle' then perform 1 from battles where id = mi.battle_id for update; if exists (select 1 from battles where id = mi.battle_id and status = 'active') then perform _resolve_battle(mi.battle_id, mi.team_id); return _cfg(v_ev, 'pts_battle'); end if; update mission_instances set status = 'failed' where id = mi.id; return 0; elsif mi.kind = 'recovery' then perform _respawn(mi.team_id, 'solved'); return 0; elsif mi.sync_round_id is not null then select * into sr from sync_rounds where id = mi.sync_round_id; v_total := greatest(1, extract(epoch from sr.deadline - sr.started_at)); v_left := greatest(0, extract(epoch from sr.deadline - now())); v_pts := round(sr.max_points * (0.5 + 0.5 * v_left / v_total)); if mt.relay and mi.fallback_at is not null and now() >= mi.fallback_at then v_pts := v_pts / 2; end if; if mi.hint_used then v_pts := round(v_pts * 0.8); end if; perform _apply(mi.team_id, 'finale', v_pts, 0, 0, 0, mi.id::text, mt.title); update teams set final_points = final_points + v_pts where id = mi.team_id; elsif mi.kind = 'airdrop' then update airdrops set claimed_by = mi.team_id, claimed_at = now(), status = 'claimed' where id = mi.airdrop_id and claimed_by is null and status = 'open' returning * into ad; v_won := ad.id is not null; if v_won then v_pts := _cfg(v_ev, 'pts_airdrop'); v_coins := case ad.tier when 'common' then 40 when 'rare' then 60 when 'legendary' then 100 when 'vault' then 120 when 'mystery' then 20 + abs(hashtext(ad.id::text)) % 101 when 'cursed' then 0 else 30 end; if ad.tier in ('cursed', 'vault') then v_pts := v_pts * 2; end if; if t.beacon then v_coins := v_coins * 2; update teams set beacon = false where id = t.id; end if; perform _apply(mi.team_id, 'airdrop', v_pts, v_coins, 0, 0, ad.id::text, ad.tier || ' airdrop'); if ad.tier = 'cursed' then perform _damage(mi.team_id, 20, 'curse', ad.id::text, 'Cursed airdrop'); end if; if ad.tier = 'intel' then update teams set scan_until = now() + interval '120 seconds' where id = t.id; end if; v_item := case ad.tier when 'legendary' then 'sniper' when 'vault' then 'sniper' when 'rare' then 'shield' when 'common' then 'medkit' when 'mystery' then (array['smg', 'jammer', 'scanner', 'extract'])[1 + abs(hashtext(ad.id::text || 'i')) % 4] else null end; if v_item is not null then perform _add_item(mi.team_id, v_item, 1); end if; if ad.tier in ('legendary', 'vault') then perform _add_item(mi.team_id, 'shield', 1); end if; if ad.tier = 'vault' then perform _add_item(mi.team_id, 'medkit', 2); end if; perform _feed(t.arena_id, 'airdrop.claimed', jsonb_build_object('team', t.number, 'tier', ad.tier, 'location', ad.location_id)); update mission_instances set status = 'cancelled' where airdrop_id = mi.airdrop_id and status = 'active' and id <> mi.id; perform _ping_arena(t.arena_id, 'airdrop'); else perform _apply(mi.team_id, 'airdrop_consolation', 0, 15, 0, 0, mi.id::text, 'Airdrop already taken'); end if; else v_pts := coalesce(mt.points, case when mt.difficulty >= 2 then _cfg(v_ev, 'pts_hard') else _cfg(v_ev, 'pts_standard') end); v_coins := mt.coins; if mt.relay then if mi.fallback_at is not null and now() >= mi.fallback_at then v_pts := v_pts / 2; elsif mi.partner_team_id is not null then perform _apply(mi.partner_team_id, 'relay_assist', _cfg(v_ev, 'pts_relay_bonus'), 0, 0, 10, mi.id::text, 'Shared a codeword'); perform _apply(mi.team_id, 'relay_trust', 0, 0, 0, 5, mi.id::text, 'Cooperated'); perform _feed(t.arena_id, 'intel.shared', jsonb_build_object('from', (select number from teams where id = mi.partner_team_id), 'to', t.number)); perform _ping_team(mi.partner_team_id, 'intel'); end if; end if; perform _apply(mi.team_id, 'mission', v_pts, v_coins, 0, 0, mi.id::text, mt.title); update teams set missions_completed = missions_completed + 1 where id = mi.team_id; select * into l from locations where id = mi.location_id; if l.id is not null and array_length(l.loot, 1) > 0 then v_item := l.loot[1 + abs(hashtext(mi.id::text)) % array_length(l.loot, 1)]; perform _add_item(mi.team_id, v_item, 1); end if; end if; update mission_instances set points_awarded = v_pts where id = mi.id; perform _feed(t.arena_id, 'mission.completed', jsonb_build_object('team', t.number, 'title', mt.title, 'points', v_pts, 'item', v_item)); perform _ping_team(mi.team_id, 'result'); perform _ping_arena(t.arena_id, 'score'); return v_pts; end $$;
